        "quote": "吐出鲜红色血液或血块"
      },
      {
        "event_id": "lite_evt_00031",
        "explanation": "The doctor identified inability to drink as an urgent warning sign.",
        "quote": "连水都喝不下"
      }
    ],
    "patient_family_realworld_adaptation": [
      {
        "event_id": "lite_evt_00204",
        "explanation": "The doctor adapted the plan to the caregiver’s real-world travel and waiting-room situation.",
        "quote": "带水少量多次抿"
      }
    ]
  },
  "dimension_ratings": {
    "actionability_responsibility_chain": "partial",
